use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap: int = 0
    let mut first = true
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut i: int = 0
            while i < ks.len() as int {
                if ks[i as usize] == k {
                    ks.remove(i as usize)
                    vs.remove(i as usize)
                } else {
                    i += 1
                }
            }
            ks.push(k)
            vs.push(v)
            if ks.len() as int > cap {
                let e = ks[0]
                ks.remove(0)
                vs.remove(0)
                println("evict ${e}")
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut found = -1
            let mut i: int = 0
            while i < ks.len() as int {
                if ks[i as usize] == k {
                    found = i
                }
                i += 1
            }
            if found < 0 {
                println("-1")
            } else {
                let v = vs[found as usize]
                ks.remove(found as usize)
                vs.remove(found as usize)
                ks.push(k)
                vs.push(v)
                println("${v}")
            }
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i: int = ks.len() as int - 1
                while i >= 0 {
                    if out != "" {
                        out = out + " "
                    }
                    out = out + "${ks[i as usize]}"
                    i -= 1
                }
                println(out)
            }
        }
    }
}

